(window.TNQ=window.TNQ||[]).push({"terms":{"원외구호":{"d":"빈민을 수용시설 밖의 자기 집에서 지원하는 구빈 방식입니다.","r":[]},"탈상품화":{"d":"노동시장에 참여하지 않고도 복지급여로 생활할 수 있는 정도를 뜻합니다.","r":["탈가족화"]},"탈가족화":{"d":"개인이 가족에 의존하지 않고도 복지로 생활할 수 있는 정도를 뜻합니다.","r":["탈상품화"]},"복지혼합":{"d":"국가, 시장, 민간, 비공식 부문이 복지를 함께 공급하는 방식입니다.","r":[]},"근로연계복지":{"d":"복지급여를 받는 조건으로 근로 활동을 요구하는 복지 방식입니다.","r":[]},"공공부조":{"d":"국가가 재정으로 빈곤층의 최저생활을 보장하는 제도입니다.","r":[]},"엥겔계수":{"d":"가계 총지출에서 식료품비가 차지하는 비율입니다.","r":[]},"무과실 책임주의":{"d":"사용자의 과실 여부와 관계없이 업무상 재해를 보상하는 원칙입니다.","r":[]},"소득재분배":{"d":"소득을 계층 사이에서 옮겨 소득 격차를 줄이는 정책 기능입니다.","r":[]},"조세저항":{"d":"조세를 낼 때 납세자가 느끼는 반발과 거부감을 뜻합니다.","r":[]},"강제가입":{"d":"가입 여부를 선택에 맡기지 않고 법으로 가입을 의무화하는 방식입니다.","r":[]}},"notes":{"개인과 집단의 박탈과 불평등을 유발하는 다양한 영역을 포괄":"개인과 집단이 무언가를 빼앗기고 불평등해지는 원인이 되는 여러 생활 영역을 모두 다룹니다.","개인의 권리와 책임의 호혜성을 강조":"복지를 받는 권리에는 그에 맞는 책임이 따른다는 상호 의무를 강조하는 관점입니다.","건강보험은 건강한 사람으로부터 질병을 겪는 사람에게 자원을 재분배":"건강보험에서는 아프지 않은 가입자의 보험료가 아픈 가입자의 진료비로 쓰이는 위험 분산이 일어납니다.","건강보험 진료비 본인부담을 정당화하는 논리로 사용":"진료를 과하게 쓰는 것을 막으려고 환자에게 진료비 일부를 내게 하는 근거로 쓰입니다.","결과의 평등보다는 기회의 평등을 강조":"발달이론은 결과를 똑같이 만들기보다 출발 기회를 공평하게 열어 주는 데 무게를 둡니다.","고소득계층에서 저소득계층으로 수직적 소득재분배기능":"소득이 높은 계층이 더 많이 부담해 낮은 계층으로 소득이 옮겨 가는 것이 수직적 재분배입니다.","고용안정과 직업능력개발사업의 보험료는 사업주가 전액부담":"고용안정사업과 직업능력개발사업의 보험료는 근로자 몫 없이 사업주가 모두 냅니다.","공공부조의 역할이 크고 탈상품화 정도는 낮음":"자유주의 복지국가는 빈곤층 선별 지원이 중심이어서 급여만으로 시장 의존을 벗어나기 어렵습니다.","국가를 포함한 복지제공의 주체를 재구성하는 논리로 활용":"국가를 포함해 복지를 공급하는 주체들의 역할을 다시 짜는 근거로 쓰이는 논리입니다.","기본적으로 소득빈곤 개념의 협소성에 대한 비판으로 이해":"사회적 배제 개념은 빈곤을 소득 부족으로만 보는 좁은 시각을 비판하며 나왔습니다.","기본적 자유에 대한 동등한 권리":"롤스의 정의론에서 모든 사람이 기본적 자유를 똑같이 누릴 권리를 가진다는 원칙입니다.","노동능력이 있는 빈민에 대한 원외구제를 폐지":"신빈민법은 일할 수 있는 빈민에게 집에서 주던 원외구제를 없애 구제를 열등처우 원칙으로 돌렸습니다.","노동능력이 있는 빈민을 교정원이나 노역장에 수용":"엘리자베스 구빈법은 일할 수 있는 빈민을 교정원이나 노역장에 가두어 일을 시켰습니다.","다른 재원에 비해 평등을 구현하는데 용이":"조세는 소득에 따라 누진적으로 걷을 수 있어서 다른 재원보다 평등 실현에 쓰기 편합니다.","모든 항목의 생계비를 계산하지 않고 엥겔계수를 활용하여 생계비를 추정":"반물량 방식은 식료품비만 구한 뒤 엥겔계수로 나누어 전체 생계비를 어림해 냅니다.","법 개정에 의해 예술인도 가입대상으로 포함":"법을 고쳐 근로자가 아닌 예술인도 고용보험에 가입할 수 있게 범위를 넓혔습니다.","보험계약이 가입자들의 행동에 영향을 미침":"보험에 가입하면 손실을 보상받으므로 가입자가 위험을 피하려는 노력을 줄이는 경향이 생깁니다.","보험료 징수업무는 국민건강보험공단이 담당":"고용보험료를 걷는 일은 고용보험 담당 기관이 아니라 국민건강보험공단이 맡고 있습니다.","복지공급의 주체로 복지혼합을 강조":"복지 공급을 국가에 맡기지 않고 시장과 민간 등 여러 주체가 섞어 맡는 구조를 내세웁니다.","복지의존의 문제를 해결하기 위해 근로연계복지를 강조":"급여에 오래 기대는 복지의존을 줄이려고 급여를 근로 활동과 묶는 방식을 내세웁니다.","부랑자들의 자유로운 이동을 금지":"일정한 거처 없이 떠도는 부랑자가 돌아다니지 못하도록 금지한 조치입니다.","불평등과 빈곤 개념은 소득의 차원을 넘어 다양한 차원으로 확대":"불평등과 빈곤은 소득 부족만이 아니라 교육, 주거, 건강 등 여러 차원의 문제로 넓혀 봅니다.","빈곤, 저학력, 열악한 주거환경 등 다양한 영역을 포괄":"사회적 배제는 소득 빈곤만이 아니라 학력과 주거 같은 여러 영역의 불리함을 함께 아우릅니다.","빈곤의 역동성과 동태적 과정을 강조":"빈곤을 한 시점의 상태로 보지 않고 사람들이 빈곤에 들어가고 벗어나는 변화 과정으로 봅니다.","빈민을 노동능력 있는 빈민, 노동능력 없는 빈민, 빈곤 아동으로 분류":"엘리자베스 구빈법은 빈민을 일할 수 있는지와 나이에 따라 세 부류로 나누어 다르게 처우했습니다.","빈민의 자유로운 이동을 제한":"정주법은 빈민이 거주 교구를 마음대로 옮기지 못하게 하여 구빈 부담이 다른 곳으로 가는 것을 막았습니다.","빈민처우의 개선을 목적으로 원외구호를 마련":"길버트법은 시설 수용만 하던 방식을 고쳐 집에서 구호받는 원외구호를 도입했습니다.","사람들이 서로 의무감과 책임감을 느끼고 함께 하려는 상태":"연대는 구성원이 서로에게 의무와 책임을 느끼며 함께하려는 마음의 상태를 가리킵니다.","사회보험은 직업집단 등에 따라 분절적으로 운영":"보수주의 복지국가는 직업별로 사회보험 제도를 따로 두어 집단마다 급여 수준이 달라집니다.","사회보험제도이므로 강제가입이 의무":"사회보험은 가입을 선택에 맡기면 위험이 낮은 사람이 빠지므로 법으로 가입을 의무화합니다.","사회복지 공급주체가 다양하게 나타나는 것":"복지다원주의는 국가뿐 아니라 시장, 민간 비영리, 가족 등이 복지를 공급하는 현상입니다.","사회복지시설의 운영을 민간에게 위탁하는 형태는 공공ㆍ민간 혼합체계의 한 종류":"재원은 공공이 대고 운영은 민간이 맡으므로 공공과 민간이 섞인 혼합체계에 속합니다.","사회적 관계망으로부터의 단절 문제를 제기":"가족, 이웃, 공동체 같은 관계망에서 끊어진 고립도 빈곤의 한 면으로 문제 삼습니다.","서비스의 지속성과 안정성 확보에 유리":"공공이 서비스를 맡으면 이용자가 꾸준히 안정적으로 서비스를 받을 수 있는 이점이 있습니다.","소극적 자유를 제한하여 위험에 직면한 사람들의 적극적 자유를 신장":"사회보험은 가입을 강제해 개인의 소극적 자유를 줄이고, 위험에 놓인 사람의 적극적 자유를 넓혀 줍니다.","소득세에 비해 상대적으로 조세저항이 약함":"사회보험료는 급여로 돌아온다는 대가성이 있어서 소득세보다 납세자의 반발이 덜합니다.","소득이나 재화뿐만 아니라 개인역량의 실현을 중심으로 판단":"센의 역량 접근은 생활수준을 소득과 재화만이 아니라 개인이 실제 할 수 있는 일로 판단합니다.","시장의 약점을 보완하고 불평등과 빈곤에 대응하기 위하여 실용적인 국가개입이 필요":"시장이 해결하지 못하는 불평등과 빈곤을 줄이려면 국가가 현실에 맞게 개입해야 한다는 입장입니다.","실업보험에서 발생할 가능성이 높다":"실업급여를 받을 수 있으면 구직 노력을 줄일 수 있어서 실업보험에서 도덕적 해이가 크게 나타납니다.","심각해지면 민간보험사의 보험료 상승으로 이어질 수 있다":"가입자의 행동 변화로 보험금 지급이 늘면 민간보험사가 손실을 메우려고 보험료를 올리게 됩니다.","업무상 재해에 대해 무과실 책임주의":"산재보험은 사업주 잘못이 없어도 업무 때문에 생긴 재해는 보상하는 무과실 책임을 따릅니다.","원칙적으로 근로자를 사용하는 모든 사업 또는 사업장에 적용":"고용보험은 근로자를 한 명이라도 쓰는 사업장에 적용하는 것을 원칙으로 합니다.","이질성과 개인화가 강조되는 상태에서 유지되는 연대":"뒤르켐이 말한 유기적 연대로, 구성원이 서로 달라 분업으로 의존하는 사회에서 유지됩니다.","일반적으로 동질성과 동등성을 갖지 못한 대상에 대한 배타성을 갖게 됨":"연대는 같은 집단 안에서 강해지므로, 성질이 다르거나 동등하지 않은 대상은 밀어내기 쉽습니다.","일정소득수준 이상이 되면 더 이상 보험료 상승이 발생하지 않음":"보험료 산정에 쓰는 소득에 상한이 있어서 그 이상 벌어도 보험료는 더 오르지 않습니다.","일정소득 이하의 빈민에게 보조금을 지급":"스핀햄랜드법은 임금이 기준 이하인 노동자에게 부족한 만큼 보조금을 얹어 주었습니다.","장애인의무고용은 연대를 제도화한 것":"장애인 의무고용은 사업주에게 고용 책임을 법으로 지워 연대를 제도로 만든 사례입니다.","재원의 안정성과 지속성이 가장 강함":"조세는 법으로 강제하여 걷으므로 복지 재원 가운데 안정적이고 꾸준하게 확보됩니다.","재해발생의 위험정도에 따라 차등적으로 부과":"산재보험료율은 업종별 재해 위험이 큰 사업장일수록 높게 정해집니다.","접근성, 통합성, 연속성, 책임성":"전달체계가 갖출 속성은 이용하기 쉽고 서비스가 통합적이며 끊기지 않고 책임 소재가 분명한 것입니다.","제도적 복지의 발달에도 불구하고 존재하는 비복지 문제에 대응하는 복지주체":"가족, 이웃, 친구 같은 비공식부문은 공식 제도가 채우지 못하는 빈틈을 메우는 주체입니다.","조세와 비교해 상대적으로 소득재분배 효과가 약함":"보험료는 소득 상한이 있고 정률로 걷는 경우가 많아 조세보다 계층 간 소득 이전이 작습니다.","최소한의 생필품을 구입하는데 필요한 비용으로 정함":"절대적 빈곤선은 생존에 꼭 필요한 물품을 사는 비용으로 정하므로 다른 사람과 견주지 않습니다.","출산 및 군복무의 경우 가입기간을 추가로 인정":"국민연금은 출산이나 군복무로 보험료를 내지 못한 기간을 가입기간에 더해 주는 크레딧 제도를 둡니다.","탈가족화 수준이 높고 계층화 수준은 낮음":"사회민주주의 복지국가는 가족 부양 부담을 국가가 덜어 주고 계층 간 급여 격차는 작습니다.","탈상품화 정도가 높고 보편적 사회서비스를 제공":"에스핑안데르센 유형에서 사회민주주의는 급여가 시장 의존을 줄이고 서비스가 모든 시민에게 갑니다.","한 사회의 평균적인 생활수준을 기준으로 정함":"상대적 빈곤선은 사회 평균에 견주어 정하므로 사회가 부유해지면 기준도 함께 올라갑니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
